// Get the cell's vertices
auto cell = c;
auto vertices = cell->vertices();
auto n_vertices = vertices.size();

// Create lifted points for each vertex with w = -time
std::array<LiftedPoint, 4> lifted_vertices;
for (auto i = 0u; i < n_vertices; ++i) {
    auto p = vertices[i]->point();
    lifted_vertices[i] = lifted_point(p.x(), p.y(), p.z(), -time);
}

// Create hyperplane from the lifted points
HyperPlane hyperplane(lifted_vertices[0], lifted_vertices[1], lifted_vertices[2], lifted_vertices[3]);

// Get the normal vector of the hyperplane
auto normal = hyperplane.normal();

// Extract the first 3 components of the normal vector as the velocity
Vector velocity(normal[0], normal[1], normal[2]);

// Normalize the velocity vector
double norm = std::sqrt(velocity.squared_length());
if (norm > std::numeric_limits<double>::epsilon()) {
    velocity /= norm;
}

return velocity;

